onboarding_slides.body:
OnboardingSlide(
  data: const {'id': 'lms.grade_capture'},
  roles: const {OnboardingRole.student},
  content: Builder(
    builder: (context) => GradeSlide(
      capture: LmsGradeCaptureAdapter(),
      onContinue: () => OnboardingSlideScope.of(context).next(),
    ),
  ),
)

integrations.replacement:
// Demo (--dart-define=IS_DEMO=true): a parent/guardian is dropped
// straight onto the partner side of the app so the reporting experience
// can be previewed without a real partner account — there is no backend
// to source the account role from. Students, and every path in
// production, keep the normal home entry below.
const isDemo = bool.fromEnvironment('IS_DEMO', defaultValue: false);
if (isDemo && role == OnboardingRole.parent) {
  context.router.replaceNamed('/partner-dashboard');
  return;
}
